  "Tabriklaymiz — siz g'olib bo'ldingiz!": { ru: 'Поздравляем — вы победили!', en: 'Congratulations — you won!' },
  "{n} so'mni {deadline} gacha (24 soat ichida) to'lashingiz kerak, aks holda auksion bekor bo'ladi va akkauntingiz 72 soatga bloklanadi.":
    { ru: 'Вы должны оплатить {n} сум до {deadline} (в течение 24 часов), иначе аукцион будет отменён, а ваш аккаунт заблокирован на 72 часа.', en: 'You must pay {n} UZS by {deadline} (within 24 hours), otherwise the auction is cancelled and your account is blocked for 72 hours.' },
  'Profilingizdagi ismingiz': { ru: 'Ваше имя в профиле', en: 'Your profile name' },
  'Telefon raqamingiz (+998...)': { ru: 'Ваш номер телефона (+998...)', en: 'Your phone number (+998...)' },
  "To'lash — {n} so'm": { ru: 'Оплатить — {n} сум', en: 'Pay — {n} UZS' },
  "To'lovga o'tish": { ru: 'Перейти к оплате', en: 'Go to payment' },
  'Narx taklif qilish': { ru: 'Предложить цену', en: 'Place a bid' },
  "Taklif berish bepul — real to'lovni faqat g'olib bo'lsangiz, 24 soat ichida qilasiz.":
    { ru: 'Ставки бесплатны — реальную оплату вы делаете только при победе, в течение 24 часов.', en: 'Bidding is free — you only make a real payment if you win, within 24 hours.' },
